tool_calls:
mkdir -p /lib; cat > /lib/utils.sh <<'EOF'
to_upper() {
  tr '[:lower:]' '[:upper:]'
}

count_lines() {
  wc -l < "$1"
}

file_size() {
  wc -c < "$1"
}
EOF
source /lib/utils.sh
printf '%s\n' 'hello world' | to_upper
count_lines /data/sample.txt
file_size /data/sample.txt

